function toast(msg){$('#notice').textContent=msg;$('#notice').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#notice').classList.remove('show'),3100);}
function commit(change){const prev=JSON.stringify(state);try{change();localStorage.setItem(key,JSON.stringify(state));return true;}catch{state=JSON.parse(prev);toast(t('空间不足，未保存。请减少照片后重试。','Storage is full. Changes were not saved. Try fewer photos.'));return false;}}
function avatar(size=''){return `<span class="avatar" ${size?`style="${size}"`:''}>${state.profile.avatar?`<img src="${escape(state.profile.avatar)}" alt="${t('我的头像','My avatar')}">`:escape([...state.profile.name].slice(0,2).join(''))}</span>`;}
const header=()=>`<header class="bar"><span class="brand">${icon('leaf')}${t('拾迹','Shiji')}</span><span class="spacer"></span>${button('profile',avatar(),'avatar-button',`aria-label="${t('我的资料','My profile')}"`)}</header>`;
const nav=()=>`<nav class="nav" aria-label="${t('主导航','Main navigation')}">${[['home','pin',t('在途','Journey')],['memories','book',t('回忆','Memories')],['profile','user',t('我的','Me')]].map(([id,ic,s])=>button(id,icon(ic)+s,view===id?'on':'',`aria-current="${view===id?'page':'false'}"`)).join('')}</nav>`;
